import{a as e,c as t,i as n,t as r}from"./app-B8uz0aqq.js";var i=JSON.parse(`{"path":"/qa/q89-rate-limiting.html","title":"Q89: 如何设计限流和防刷机制？","lang":"en-US","frontmatter":{},"filePathRelative":"qa/q89-rate-limiting.md","git":{"createdTime":1773965296000,"updatedTime":1773965296000,"contributors":[{"name":"cuihairu","username":"cuihairu","email":"chuihairu@gmail.com","commits":1,"url":"https://github.com/cuihairu"},{"name":"Claude Opus 4.6 (1M context)","username":"","email":"noreply@anthropic.com","commits":1}]}}`),a={name:`q89-rate-limiting.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="q89-如何设计限流和防刷机制" tabindex="-1"><a class="header-anchor" href="#q89-如何设计限流和防刷机制"><span>Q89: 如何设计限流和防刷机制？</span></a></h1><h2 id="问题分析" tabindex="-1"><a class="header-anchor" href="#问题分析"><span>问题分析</span></a></h2><p>本题考察对限流防刷的理解：</p><ul><li>限流算法</li><li>防刷策略</li><li>令牌桶</li><li>漏桶算法</li></ul><hr><h2 id="一、限流算法" tabindex="-1"><a class="header-anchor" href="#一、限流算法"><span>一、限流算法</span></a></h2><h3 id="_1-1-令牌桶" tabindex="-1"><a class="header-anchor" href="#_1-1-令牌桶"><span>1.1 令牌桶</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 令牌桶算法</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">TokenBucketRateLimiter</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token function">TokenBucketRateLimiter</span><span class="token punctuation">(</span>size_t capacity<span class="token punctuation">,</span> size_t refillRate<span class="token punctuation">)</span></span>
<span class="line">        <span class="token operator">:</span> <span class="token function">capacity_</span><span class="token punctuation">(</span>capacity<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">refillRate_</span><span class="token punctuation">(</span>refillRate<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">          <span class="token function">tokens_</span><span class="token punctuation">(</span>capacity<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token function">lastRefill_</span><span class="token punctuation">(</span><span class="token function">getCurrentTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">bool</span> <span class="token function">allowRequest</span><span class="token punctuation">(</span><span class="token keyword">int</span> tokens <span class="token operator">=</span> <span class="token number">1</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">uint64_t</span> now <span class="token operator">=</span> <span class="token function">getCurrentTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 补充令牌</span></span>
<span class="line">        <span class="token function">refill</span><span class="token punctuation">(</span>now<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 检查是否有足够令牌</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>tokens_ <span class="token operator">&gt;=</span> tokens<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            tokens_ <span class="token operator">-=</span> tokens<span class="token punctuation">;</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">private</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">void</span> <span class="token function">refill</span><span class="token punctuation">(</span><span class="token keyword">uint64_t</span> now<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">uint64_t</span> elapsed <span class="token operator">=</span> now <span class="token operator">-</span> lastRefill_<span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">uint64_t</span> tokensToAdd <span class="token operator">=</span> <span class="token punctuation">(</span>elapsed <span class="token operator">*</span> refillRate_<span class="token punctuation">)</span> <span class="token operator">/</span> <span class="token number">1000</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        tokens_ <span class="token operator">=</span> std<span class="token double-colon punctuation">::</span><span class="token function">min</span><span class="token punctuation">(</span>capacity_<span class="token punctuation">,</span> tokens_ <span class="token operator">+</span> tokensToAdd<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        lastRefill_ <span class="token operator">=</span> now<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    size_t capacity_<span class="token punctuation">;</span>    <span class="token comment">// 桶容量</span></span>
<span class="line">    size_t refillRate_<span class="token punctuation">;</span>  <span class="token comment">// 补充速率 (tokens/second)</span></span>
<span class="line">    size_t tokens_<span class="token punctuation">;</span>      <span class="token comment">// 当前令牌数</span></span>
<span class="line">    <span class="token keyword">uint64_t</span> lastRefill_<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="二、应用场景" tabindex="-1"><a class="header-anchor" href="#二、应用场景"><span>二、应用场景</span></a></h2><h3 id="_2-1-多级限流" tabindex="-1"><a class="header-anchor" href="#_2-1-多级限流"><span>2.1 多级限流</span></a></h3><div class="language-cpp line-numbers-mode" data-highlighter="prismjs" data-ext="cpp"><pre><code class="language-cpp"><span class="line"><span class="token comment">// 多级限流系统</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">class</span> <span class="token class-name">RateLimiter</span> <span class="token punctuation">{</span></span>
<span class="line"><span class="token keyword">public</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">enum</span> <span class="token keyword">class</span> <span class="token class-name">LimitResult</span> <span class="token punctuation">{</span></span>
<span class="line">        ALLOW<span class="token punctuation">,</span></span>
<span class="line">        WARN<span class="token punctuation">,</span></span>
<span class="line">        DENY</span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    LimitResult <span class="token function">check</span><span class="token punctuation">(</span><span class="token keyword">uint64_t</span> playerId<span class="token punctuation">,</span> <span class="token keyword">const</span> std<span class="token double-colon punctuation">::</span>string<span class="token operator">&amp;</span> action<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token comment">// 检查个人限制</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token function">checkPlayerLimit</span><span class="token punctuation">(</span>playerId<span class="token punctuation">,</span> action<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> LimitResult<span class="token double-colon punctuation">::</span>DENY<span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 检查 IP 限制</span></span>
<span class="line">        std<span class="token double-colon punctuation">::</span>string ip <span class="token operator">=</span> <span class="token function">getPlayerIP</span><span class="token punctuation">(</span>playerId<span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token function">checkIPLimit</span><span class="token punctuation">(</span>ip<span class="token punctuation">,</span> action<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> LimitResult<span class="token double-colon punctuation">::</span>DENY<span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 检查全局限制</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token operator">!</span><span class="token function">checkGlobalLimit</span><span class="token punctuation">(</span>action<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> LimitResult<span class="token double-colon punctuation">::</span>WARN<span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">return</span> LimitResult<span class="token double-colon punctuation">::</span>ALLOW<span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">private</span><span class="token operator">:</span></span>
<span class="line">    <span class="token keyword">bool</span> <span class="token function">checkPlayerLimit</span><span class="token punctuation">(</span><span class="token keyword">uint64_t</span> playerId<span class="token punctuation">,</span> <span class="token keyword">const</span> std<span class="token double-colon punctuation">::</span>string<span class="token operator">&amp;</span> action<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">        PlayerLimits<span class="token operator">&amp;</span> limits <span class="token operator">=</span> playerLimits_<span class="token punctuation">[</span>playerId<span class="token punctuation">]</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">uint64_t</span> now <span class="token operator">=</span> <span class="token function">getCurrentTime</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">uint64_t</span> window <span class="token operator">=</span> <span class="token number">60000</span><span class="token punctuation">;</span>  <span class="token comment">// 1分钟窗口</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 滑动窗口计数</span></span>
<span class="line">        limits<span class="token punctuation">.</span>counter<span class="token operator">++</span><span class="token punctuation">;</span></span>
<span class="line">        limits<span class="token punctuation">.</span>windowStart <span class="token operator">=</span> now<span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">        <span class="token comment">// 1分钟内最多 100 次</span></span>
<span class="line">        <span class="token keyword">if</span> <span class="token punctuation">(</span>limits<span class="token punctuation">.</span>counter <span class="token operator">&gt;</span> <span class="token number">100</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">            <span class="token keyword">return</span> <span class="token boolean">false</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">true</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line">    <span class="token keyword">struct</span> <span class="token class-name">PlayerLimits</span> <span class="token punctuation">{</span></span>
<span class="line">        <span class="token keyword">uint64_t</span> counter <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">        <span class="token keyword">uint64_t</span> windowStart <span class="token operator">=</span> <span class="token number">0</span><span class="token punctuation">;</span></span>
<span class="line">    <span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span>
<span class="line">    std<span class="token double-colon punctuation">::</span>unordered_map<span class="token operator">&lt;</span><span class="token keyword">uint64_t</span><span class="token punctuation">,</span> PlayerLimits<span class="token operator">&gt;</span> playerLimits_<span class="token punctuation">;</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">;</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="三、总结" tabindex="-1"><a class="header-anchor" href="#三、总结"><span>三、总结</span></a></h2><h3 id="限流防刷核心" tabindex="-1"><a class="header-anchor" href="#限流防刷核心"><span>限流防刷核心</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">限流防刷 = 令牌桶 + 滑动窗口 + 多级防护</span>
<span class="line">- 令牌桶算法</span>
<span class="line">- 滑动窗口计数</span>
<span class="line">- 个人/IP/全局三级</span>
<span class="line">- 超限返回错误</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li><a href="https://konghq.com/blog/how-to-design-a-scalable-rate-limiting-service/" target="_blank" rel="noopener noreferrer">Rate Limiting Algorithms</a></li><li><a href="https://en.wikipedia.org/wiki/Token_bucket" target="_blank" rel="noopener noreferrer">Token Bucket Wikipedia</a></li></ul>`,19)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};